"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["93620"],{59271(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.fase_cronograma.janela_invertida","status":422,"titulo":"A data de t\xe9rmino do per\xedodo da fase \xe9 anterior \xe0 data de in\xedcio"},"descricao":{"codigo":"uniplus.selecao.fase_cronograma.janela_invertida","requisitos":[],"oQueAconteceu":["Uma fase do cronograma foi declarada com `inicio` e `fim` e o `fim` \xe9 anterior ao\\n`inicio`. O per\xedodo com fim igual ao in\xedcio \xe9 aceito; s\xf3 o fim anterior ao in\xedcio \xe9\\nrecusado. A recusa vem em `fases[n].fim`, e a mensagem traz o c\xf3digo da fase e os\\ndois instantes.","A confer\xeancia vale seja qual for a origem da data da fase: mesmo a fase cuja data\\n\xe9 definida na execu\xe7\xe3o, e n\xe3o no edital, n\xe3o pode ser declarada com per\xedodo\\ninvertido. Ela \xe9 feita ao montar cada fase, junto com as outras viola\xe7\xf5es da\\nmesma fase (atos repetidos, parecer individual sem resultado, por exemplo), e\\ns\xf3 para a fase cujos atos foram montados sem recusa; por isso uma viola\xe7\xe3o nos\\natos de uma fase pode esconder, at\xe9 ser corrigida, o per\xedodo invertido dela."],"comoResolver":["Corrija `inicio` e `fim` da fase para que o fim seja igual ou posterior ao in\xedcio\\n(confira o fuso e o dia, que costumam estar trocados) e repita a defini\xe7\xe3o do\\ncronograma. O per\xedodo da fase tamb\xe9m \xe9 conferido, depois, contra os das preced\xeancias\\ne os das etapas da fase, que t\xeam recusas pr\xf3prias."],"ondeAparece":["Defini\xe7\xe3o do cronograma de fases do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Fase cronograma"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"fd5ea0ff72951399d2b2c1a4f29aeb3ea415db44"}}')}}]);